from review import card,save,DATE
i='TCS-3689';_,c=card(i);refs=c['references'];refs[0]['locator']='Definitions 7 and 9, finite-domain convention after Theorem 11; Section 6, Proposition 25 and maximum classes; Section 8 explicitly asks whether NCTD≤VCD in general.'
refs += [dict(id='journal',title='On Batch Teaching Without Collusion',authors='Shaun Fallat; David Kirkpatrick; Hans U. Simon; Abolghasem Soltani; Sandra Zilles',year=2023,url='https://www.jmlr.org/papers/v24/22-0330.html',pdf_url='https://www.jmlr.org/papers/volume24/22-0330/22-0330.pdf',locator='JMLR catalogue 24(40), 2023, pages 1–33; supplied PDF header dates December 2022. Discussion of NCTD and VCD, finite maximum classes, and final open question; separates stronger collusion criteria.'),dict(id='balls',title='Non-Clashing Teaching Maps for Balls in Graphs',authors='Jérémie Chalopin; Victor Chepoi; Fionn Mc Inerney; Sébastien Ratel',year=2024,url='https://proceedings.mlr.press/v247/chalopin24a.html',pdf_url='https://proceedings.mlr.press/v247/chalopin24a/chalopin24a.pdf',locator='COLT 2024; introduction repeats the exact general inequality question; special graph-class results and positive-example variant; conclusion.')]
notes=['Recovered the sharp universal NCTD≤VC inequality from the source conclusion, not merely an unspecified relationship.','Defined finite signed teaching sets, consistency, pairwise no-clash condition, the worst-case minimum and shattering.','Separated ordinary and positive-only teaching, stronger collusion criteria and sample compression.','Checked the 2023 journal treatment and 2024 graph-class advances; neither the quadratic bound nor separate upper bounds provide the sharp general inequality or a counterexample.']
save(i,dict(title='Non-clashing teaching dimension versus VC dimension',formal='For every finite set X and every nonempty concept class C⊆2ˣ, is NCTD(C)≤VC(C)? Equivalently, if C has VC dimension d, does there exist a teaching map assigning at most d correctly labeled examples to each concept such that no two distinct concepts are mutually consistent with one another’s assigned examples? Both positive and negative examples are allowed. The target constant is exactly one, not merely a bound O(d).',definitions='A concept C∈C is a subset of the finite instance set X, identified with its indicator function 1_C:X→{0,1}. A labeled sample is an unordered subset of X×{0,1}. It is consistent with C if each (x,y) in it has y=1_C(x). A teaching map T assigns a sample T(C) consistent with C to every concept C in the class. It is non-clashing if, for every distinct C,D∈C, T(C) is not consistent with D or T(D) is not consistent with C. Equivalently, some point appearing in either teaching set has different labels under C and D. The condition is pairwise: T(C) need not by itself distinguish C from every other concept. A positive example has label 1 and a negative example has label 0; both count as one example. The size of T is max_{C∈C}|T(C)|, and NCTD(C) is the minimum of that size over all non-clashing teaching maps. The minimum exists because X and C are finite and giving all labels is a valid map. No sample order, extra message or additional side information is part of this definition. A subset S⊆X is shattered by C when {C∩S:C∈C}=2ˢ. The VC dimension VC(C) is the maximum cardinality of a shattered set. For a singleton concept class it is zero, and the empty teaching set works. The statement quantifies over all finite X and nonempty C, including that case; it concerns existence of a map, without an efficiency or encoding-size requirement on constructing it. The positive-only parameter NCTD⁺ restricts T(C) to samples with label 1 and can be larger. It is not the parameter in this conjecture.',question_type='yes_no',answer_criterion='Prove the exact inequality for every finite concept class by establishing existence of a valid map of maximum size at most its VC dimension, or give a finite concept class and a proof that every non-clashing teaching map has larger maximum size. A quadratic bound or even a larger-constant linear bound is insufficient. A separation for positive-only maps, another teaching model, or an algorithmic hardness result for finding maps does not refute this existence statement.',context_blocks=[dict(title='Known general bounds leave a substantial gap',text='The source and journal article give a universal upper bound quadratic in VC dimension. Their conclusion asks for the sharper inequality with coefficient one, and reports no counterexample to that inequality.',citation='journal'),dict(title='Finite maximum classes satisfy the target',text='If a class of VC dimension d on X attains Sauer’s size bound Σ_{i=0}^d binomial(|X|,i), the cited representation-map result supplies a non-clashing map of size d. Maximum classes are a special case, not all finite classes.',citation='primary'),dict(title='Graph-ball results provide further special cases',text='The COLT 2024 paper constructs small maps for balls in particular graph classes and explicitly repeats the general open question. A size-four upper bound together with a VC-dimension-three upper bound for another family does not prove NCTD exceeds VC there.',citation='balls'),dict(title='The teaching convention matters',text='The journal article separately studies stronger restrictions on avoiding collusion. Their optimal teaching parameter need not equal NCTD. Likewise, a map for the concepts themselves is not automatically a sample-compression scheme that must reconstruct from arbitrary samples.',citation='journal')],why='Would show that every finite concept class can be taught with at most its VC dimension many examples per concept in the non-clashing model, giving a sharp link between learning capacity and teaching complexity.',references=refs,progress=[dict(date='2019',text='The ALT paper defines NCTD, proves general and special-case bounds, and asks for the exact inequality NCTD≤VC.',citation='primary'),dict(date='2023',text='The expanded JMLR article retains the universal question and distinguishes stronger teaching restrictions.',citation='journal'),dict(date='2024',text='COLT results establish additional bounds for graph-ball classes and explicitly preserve the general conjecture.',citation='balls')],status='open',status_note='Read the finite-domain no-clash definition and conclusion, the expanded JMLR treatment, and the COLT 2024 special-case results. Later searches through 12 September 2026 also found work on computing positive graph-ball teaching maps, but no proof or counterexample to the universal signed NCTD≤VC inequality. Search is not exhaustive.',model_self_contained=True,requires_context=False,review_note='Recovered the exact coefficient-one inequality for finite classes, with complete signed-sample and no-clash definitions.',importance=dict(score=c['importance']['score'],method='editorial',reason='A broad sharp relation between VC dimension and the minimal non-clashing teaching-set size, identified as fundamental in the source and later work. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['A teacher assigns correctly labeled examples to each concept in a finite class.','No two different concepts may both fit each other’s assigned examples.','The conjecture asks whether at most d examples per concept always suffice when the VC dimension is d.','A quadratic general bound and exact bounds for certain special classes are known.','The sharp signed-example inequality remains distinct from positive-only teaching, computational map-finding and sample-compression questions.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','journal','balls'])),notes=notes,checked_sources=[r['url'] for r in refs]+['https://proceedings.iclr.cc/paper_files/paper/2025/file/6e1caf62e7074b95aaa8904d44e02054-Paper-Conference.pdf'])
